CREATE TABLE stadio (
  id_stadio int NOT NULL AUTO_INCREMENT,
  nome_stadio varchar(100) NOT NULL,
  indirizzo varchar(100) DEFAULT NULL,
  capienza int DEFAULT NULL,
  latitudine varchar(100) DEFAULT NULL,
  longitudine varchar(100) DEFAULT NULL,
  foto_stadio varchar(200) DEFAULT NULL,
  immagine_stadio varchar(600) DEFAULT NULL,
  PRIMARY KEY (id_stadio)
) 

